"use client";

import { memo, type PointerEvent, type ReactNode } from "react";
import * as motion from 'motion/react-client';
import { useMotionTemplate, useReducedMotion, useSpring } from "motion/react";
import { cn } from "cn";
import { Card } from "./card";

export type BorderHighlightProps = {
  children?: ReactNode;
  className?: string;
};

export const BorderHighlight = memo(function BorderHighlight({
  children = <Card title="Follow the edge" description="Move your pointer around this card to reveal a glowing border." className="max-w-none border-0 bg-transparent shadow-none" />,
  className,
}: BorderHighlightProps = {}) {
  const reducedMotion = useReducedMotion();
  const x = useSpring(0, { stiffness: 300, damping: 30 });
  const y = useSpring(0, { stiffness: 300, damping: 30 });
  const mask = useMotionTemplate`radial-gradient(circle 180px at ${x}px ${y}px, black 20%, transparent 100%)`;

  function trackPointer(event: PointerEvent<HTMLDivElement>) {
    if (event.pointerType === "touch") return;
    const bounds = event.currentTarget.getBoundingClientRect();
    const nextX = event.clientX - bounds.left;
    const nextY = event.clientY - bounds.top;
    if (event.type === "pointerenter" || reducedMotion) {
      x.jump(nextX);
      y.jump(nextY);
    } else {
      x.set(nextX);
      y.set(nextY);
    }
  }

  return (
    <motion.div
      initial="rest"
      whileHover="hover"
      onPointerEnter={trackPointer}
      onPointerMove={trackPointer}
      className={cn("relative w-96 max-w-full min-w-0 border border-border bg-card p-3 text-card-foreground transition-colors hover:border-border/20 focus-within:border-primary/50 motion-reduce:transition-none md:p-4", className)}
    >
      {children}
      <motion.div
        aria-hidden="true"
        className="pointer-events-none absolute -inset-px rounded-[inherit] border-2 border-primary shadow-[0_0_20px_color-mix(in_srgb,var(--primary)_25%,transparent)]"
        variants={{ rest: { opacity: 0 }, hover: { opacity: 1 } }}
        transition={{ duration: reducedMotion ? 0 : 0.2 }}
        style={{ maskImage: mask, WebkitMaskImage: mask }}
      />
    </motion.div>
  );
});

import { typography } from "../lib/typography.shared";
import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-base leading-7 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className={typography.sectionTitle}>{title}</h3>}
    {description && <p className={`mt-2 ${typography.body}`}>{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}

/** Shared text hierarchy for documentation and component content. */
export const typography = {
  pageTitle: "text-4xl font-semibold tracking-tight text-foreground sm:text-5xl",
  sectionTitle: "text-2xl font-semibold tracking-tight text-foreground",
  subsectionTitle: "text-xl font-semibold tracking-tight text-foreground",
  body: "text-base leading-7 text-muted-foreground",
  label: "text-sm font-medium",
  caption: "text-sm leading-6 text-muted-foreground",
} as const;
